link.script:
[
  {
    "@context": "https://schema.org",
    "@type": "TravelAgency",
    "@id": "https://mytourism.ae/#organization",
    "name": "MY Tourism",
    "image": "https://mytourism.ae/images/lexus-300-black.avif",
    "url": "https://mytourism.ae",
    "telephone": "+971561402248",
    "email": "eworldnetwork2020@gmail.com",
    "priceRange": "$$$",
    "address": {
      "@type": "PostalAddress",
      "streetAddress": "Al Ain Centre (Computer Plaza), Bur Dubai",
      "addressLocality": "Bur Dubai, Dubai",
      "addressRegion": "Dubai",
      "addressCountry": "AE"
    },
    "geo": {
      "@type": "GeoCoordinates",
      "latitude": 25.2532,
      "longitude": 55.3005
    },
    "openingHoursSpecification": {
      "@type": "OpeningHoursSpecification",
      "dayOfWeek": [
        "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"
      ],
      "opens": "00:00",
      "closes": "23:59"
    },
    "aggregateRating": {
      "@type": "AggregateRating",
      "ratingValue": "5.0",
      "reviewCount": "100"
    },
    "review": [
      {
        "@type": "Review",
        "author": { "@type": "Person", "name": "Ahmed Al-Maktoum" },
        "reviewRating": { "@type": "Rating", "ratingValue": "5" },
        "reviewBody": "Exceptional service! The BMW 7 Series was spotless, and the driver was extremely professional and punctual for our corporate meetings in Dubai."
      },
      {
        "@type": "Review",
        "author": { "@type": "Person", "name": "Sarah Jenkins" },
        "reviewRating": { "@type": "Rating", "ratingValue": "5" },
        "reviewBody": "Booked a Desert Safari with Quad Biking and BBQ dinner for our family. Hands down the best experience in Dubai! Smooth booking on WhatsApp."
      },
      {
        "@type": "Review",
        "author": { "@type": "Person", "name": "Michael Vance" },
        "reviewRating": { "@type": "Rating", "ratingValue": "5" },
        "reviewBody": "Outstanding luxury experience! The Lexus sedan and Mercedes driver were courteous and knowledgeable during our full-day Dubai city tour."
      }
    ],
    "hasOfferCatalog": {
      "@type": "OfferCatalog",
      "name": "Dubai Tourism & Chauffeur Services",
      "itemListElement": [
        {
          "@type": "Offer",
          "itemOffered": {
            "@type": "Service",
            "name": "Desert Safari With Quad Bike",
            "description": "Red dune bashing, quad bike ride, sandboarding, camel ride, live shows & BBQ buffet dinner."
          },
          "price": "299",
          "priceCurrency": "AED"
        },
        {
          "@type": "Offer",
          "itemOffered": {
            "@type": "Service",
            "name": "Private VIP Desert Safari",
            "description": "Exclusive private Land Cruiser pickup, dune driving, camel rides, camp entertainment and BBQ dinner."
          },
          "price": "699",
          "priceCurrency": "AED"
        },
        {
          "@type": "Offer",
          "itemOffered": {
            "@type": "Service",
            "name": "Desert Safari BBQ Dinner (Shared)",
            "description": "Dune driving, camel riding, sandboarding, Henna painting, Tanoura show & international BBQ dinner."
          },
          "price": "99",
          "priceCurrency": "AED"
        },
        {
          "@type": "Offer",
          "itemOffered": {
            "@type": "Service",
            "name": "Full Day Dubai City Tour",
            "description": "Guided tour covering Burj Khalifa, Dubai Mall, Atlantis The Palm, Dubai Frame, Gold Souk, and Dubai Marina."
          },
          "price": "600",
          "priceCurrency": "AED"
        },
        {
          "@type": "Offer",
          "itemOffered": {
            "@type": "Service",
            "name": "Full Day Abu Dhabi City Tour",
            "description": "Grand Mosque, Heritage Village, Emirates Palace, Louvre Museum photo stop, and Ferrari World view."
          },
          "price": "700",
          "priceCurrency": "AED"
        },
        {
          "@type": "Offer",
          "itemOffered": {
            "@type": "Service",
            "name": "Luxury Chauffeur & Monthly Car Lift",
            "description": "Executive private transfers, monthly car lifts, and inter-emirates chauffeur services across Dubai, Abu Dhabi, and Sharjah."
          }
        }
      ]
    }
  },
  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "How do I book your ride or luxury chauffeur service with MY Tourism?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "You can book your ride instantly through our quick inquiry form on the website or connect directly with our team via WhatsApp at +971 561402248."
        }
      },
      {
        "@type": "Question",
        "name": "What is included in the Dubai Desert Safari packages?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Our desert safari packages typically include red dune bashing, camel riding, sandboarding, live entertainment shows, and an international BBQ buffet dinner, with options to include a quad bike ride."
        }
      },
      {
        "@type": "Question",
        "name": "Are petrol, Salik, and insurance included in luxury car and chauffeur rentals?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes! For our hourly luxury fleet rentals (such as the Lexus 300H, Mercedes, and vans/buses), the price includes comprehensive insurance, petrol, Salik (toll gates), parking, Wi-Fi, and bottled water."
        }
      },
      {
        "@type": "Question",
        "name": "Do you provide airport transfer services at Dubai International Airport (DXB)?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes, we offer 24/7 airport transfer services with professional meet-and-greet options across Dubai, Abu Dhabi, and Sharjah airports using our entire luxury fleet."
        }
      },
      {
        "@type": "Question",
        "name": "Is there an extra surcharge for trips outside Dubai, such as to Abu Dhabi?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes, inter-emirates transfers to Abu Dhabi or other locations outside Dubai incur a standard extra surcharge ranging from AED 100 to AED 300 depending on the specific vehicle type."
        }
      }
    ]
  }
]

body.script:
  let iti;
  let itiInitialized = false;

  window.addEventListener("DOMContentLoaded", function() {
    const phoneInput = document.querySelector("#wa");
    
    if (phoneInput) {
      const initIti = () => {
        if (!itiInitialized && window.intlTelInput) {
          iti = window.intlTelInput(phoneInput, {
            initialCountry: "ae",
            separateDialCode: true,
            preferredCountries: ["ae", "sa", "qa", "om", "kw", "bh", "gb", "us", "in", "pk"],
            utilsScript: "https://cdnjs.cloudflare.com/ajax/libs/intl-tel-input/17.0.19/js/utils.js"
          });
          itiInitialized = true;
        }
      };

      phoneInput.addEventListener("focus", initIti, { once: true });
      phoneInput.addEventListener("click", initIti, { once: true });
    }
  });

  function openWhats(vehicleName) {
    const phone = "971561402248";
    const text = encodeURIComponent(`Hello, I would like a WhatsApp Quick Inquiry for: ${vehicleName}`);
    window.open(`https://wa.me/${phone}?text=${text}`, '_blank');
  }

  function handleQuick(event) {
    event.preventDefault();
    const phone = "971561402248";
    const fullUserWa = iti ? iti.getNumber() : document.getElementById('wa').value;
    const loc = document.getElementById('loc').value;
    const when = document.getElementById('when').value;
    const what = document.getElementById('what').value;

    const message = encodeURIComponent(`Book Your Ride Now / Trip Inquiry:\nService/Vehicle: ${what}\nPickup Location: ${loc}\nDate & Time: ${when}\nClient WhatsApp: ${fullUserWa}`);
    window.open(`https://wa.me/${phone}?text=${message}`, '_blank');
  }

  function scrollToCard(cardId) {
    const cardElement = document.getElementById(cardId);
    if (cardElement) {
      cardElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
      cardElement.style.transition = 'box-shadow 0.4s ease, border-color 0.4s ease';
      cardElement.style.boxShadow = '0 0 25px rgba(245, 158, 11, 0.6)';
      cardElement.style.borderColor = '#f59e0b';
      setTimeout(() => {
        cardElement.style.boxShadow = '0 4px 6px -1px rgba(0, 0, 0, 0.05)';
        cardElement.style.borderColor = '#e2e8f0';
      }, 1500);
    }
  }
